const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function normalize(value) {
  return value === undefined || value === null
    ? ""
    : String(value).trim().toLowerCase();
}

function safe(value, fallback = null) {
  return value === undefined || value === null || value === "" ? fallback : value;
}

function makeResponseId(approvalId, eventId) {
  const base = approvalId || eventId || "unknown_approval";
  const suffix = Date.now().toString(36);
  return `approval_response_${base}_${suffix}`.replace(/[^a-zA-Z0-9_]/g, "_");
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-O2",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        approval_response: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-O2 will not capture response when upstream approval flow failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "capture_approval_response") {
  return fail({
    code: "APPROVAL_RESPONSE_NOT_REQUESTED",
    message: "source.next_action is not capture_approval_response.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!source.approval || typeof source.approval !== "object") {
  return fail({
    code: "MISSING_APPROVAL_OBJECT",
    message: "input.approval is required."
  });
}

if (!source.response || typeof source.response !== "object") {
  return fail({
    code: "MISSING_RESPONSE_OBJECT",
    message: "input.response is required."
  });
}

const approval = source.approval;
const response = source.response;

if (!approval.approval_id) {
  return fail({
    code: "MISSING_APPROVAL_ID",
    message: "approval.approval_id is required."
  });
}

const decision = normalize(response.decision);

if (!decision) {
  return fail({
    code: "MISSING_DECISION",
    message: "response.decision is required."
  });
}

const allowedActions = Array.isArray(approval.allowed_actions)
  ? approval.allowed_actions.map(normalize)
  : ["approve", "reject", "revise"];

if (!allowedActions.includes(decision)) {
  return fail({
    code: "INVALID_DECISION",
    message: "response.decision is not included in approval.allowed_actions.",
    details: [
      {
        decision,
        allowed_actions: allowedActions
      }
    ]
  });
}

if (!response.reviewer_email) {
  return fail({
    code: "MISSING_REVIEWER_EMAIL",
    message: "response.reviewer_email is required."
  });
}

const expectedReviewer = normalize(approval.reviewer_email);
const actualReviewer = normalize(response.reviewer_email);

if (expectedReviewer && actualReviewer && expectedReviewer !== actualReviewer) {
  return fail({
    code: "REVIEWER_MISMATCH",
    message: "response.reviewer_email does not match approval.reviewer_email.",
    details: [
      {
        expected_reviewer: approval.reviewer_email,
        actual_reviewer: response.reviewer_email
      }
    ]
  });
}

const submittedAt = response.submitted_at || nowIso();
const decisionActionMap = config.decision_action_map || {};
const mappedAction = decisionActionMap[decision] || decision;

let approvalStatus = "decided";

if (decision === "approve") approvalStatus = "approved";
if (decision === "reject") approvalStatus = "rejected";
if (decision === "revise") approvalStatus = "revision_requested";

const approvalResponse = {
  response_id: makeResponseId(approval.approval_id, source.event_id),
  approval_id: approval.approval_id,
  approval_type: safe(approval.approval_type),
  approval_title: safe(approval.approval_title),
  previous_status: safe(approval.status),
  decision,
  approval_status: approvalStatus,
  reviewer_email: response.reviewer_email,
  reviewer_notes: response.reviewer_notes || "",
  submitted_at: submittedAt,
  source_component: source.component_id || null,
  source_component_version: source.component_version || null,
  event_id: source.event_id || null,
  event_type: source.event_type || null,
  context: approval.context || {},
  decision_action: mappedAction
};

return [
  {
    json: {
      success: true,
      component_id: "C2-O2",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      approval_response: approvalResponse,
      source_result: source,
      error: null,
      next_action: config.default_next_action || mappedAction
    }
  }
];
